7	import type { Settings } from '../config/settings.js';
8	import type {
9	  SettingDefinition,
10	  SettingsSchema,
11	  SettingsType,
12	  SettingsValue,
13	} from '../config/settingsSchema.js';
14	import { getSettingsSchema } from '../config/settingsSchema.js';
15	import type { Config } from '@google/gemini-cli-core';
16	import { ExperimentFlags } from '@google/gemini-cli-core';
17	
18	// The schema is now nested, but many parts of the UI and logic work better
19	// with a flattened structure and dot-notation keys. This section flattens the
20	// schema into a map for easier lookups.
21	
22	type FlattenedSchema = Record<string, SettingDefinition & { key: string }>;
23	
24	function flattenSchema(schema: SettingsSchema, prefix = ''): FlattenedSchema {
25	  let result: FlattenedSchema = {};
26	  for (const key in schema) {
27	    const newKey = prefix ? `${prefix}.${key}` : key;
28	    const definition = schema[key];
29	    result[newKey] = { ...definition, key: newKey };
30	    if (definition.properties) {
31	      result = { ...result, ...flattenSchema(definition.properties, newKey) };
32	    }
33	  }
34	  return result;
35	}
36	
37	let _FLATTENED_SCHEMA: FlattenedSchema | undefined;
38	
39	/** Returns a flattened schema, the first call is memoized for future requests. */
40	export function getFlattenedSchema() {
41	  return (
42	    _FLATTENED_SCHEMA ??
43	    (_FLATTENED_SCHEMA = flattenSchema(getSettingsSchema()))
44	  );
45	}
46	
47	function clearFlattenedSchema() {
48	  _FLATTENED_SCHEMA = undefined;
49	}
50	
51	export function getSettingsByCategory(): Record<
52	  string,
53	  Array<SettingDefinition & { key: string }>
54	> {
55	  const categories: Record<
56	    string,
57	    Array<SettingDefinition & { key: string }>
58	  > = {};
59	
60	  Object.values(getFlattenedSchema()).forEach((definition) => {
61	    const category = definition.category;
62	    if (!categories[category]) {
63	      categories[category] = [];
64	    }
65	    categories[category].push(definition);
66	  });
67	
68	  return categories;
69	}
70	
71	export function getSettingDefinition(
72	  key: string,
73	): (SettingDefinition & { key: string }) | undefined {
74	  return getFlattenedSchema()[key];
75	}
76	
77	export function requiresRestart(key: string): boolean {
78	  return getFlattenedSchema()[key]?.requiresRestart ?? false;
79	}
80	
81	export function getDefaultValue(key: string): SettingsValue {
82	  return getFlattenedSchema()[key]?.default;
83	}
84	
85	/**
86	 * Get the effective default value for a setting, checking experiment values when available.
87	 * For settings like compressionThreshold, this will return the experiment value if set,
88	 * otherwise falls back to the schema default.
89	 */
90	export function getEffectiveDefaultValue(
91	  key: string,
92	  config?: Config,
93	): SettingsValue {
94	  if (key === 'model.compressionThreshold' && config) {
95	    const experiments = config.getExperiments();
96	    const experimentValue =
97	      experiments?.flags[ExperimentFlags.CONTEXT_COMPRESSION_THRESHOLD]
98	        ?.floatValue;
99	    if (experimentValue !== undefined && experimentValue !== 0) {
100	      return experimentValue;
101	    }
102	  }
103	
104	  return getDefaultValue(key);
105	}
106	
107	export function getRestartRequiredSettings(): string[] {
108	  return Object.values(getFlattenedSchema())
109	    .filter((definition) => definition.requiresRestart)
110	    .map((definition) => definition.key);
111	}
112	
113	/**
114	 * Get restart-required setting keys that are also visible in the dialog.
115	 * Non-dialog restart keys (e.g. parent container objects like mcpServers, tools)
116	 * are excluded because users cannot change them through the dialog.
117	 */
118	export function getDialogRestartRequiredSettings(): string[] {
119	  return Object.values(getFlattenedSchema())
120	    .filter(
121	      (definition) =>
122	        definition.requiresRestart && definition.showInDialog !== false,
123	    )
124	    .map((definition) => definition.key);
125	}
126	
127	export function isRecord(value: unknown): value is Record<string, unknown> {
128	  return typeof value === 'object' && value !== null;
129	}
130	
131	function isSettingsValue(value: unknown): value is SettingsValue {
132	  if (value === undefined) return true;
133	  if (value === null) return false;
134	  const type = typeof value;
135	  return (
136	    type === 'string' ||
137	    type === 'number' ||
138	    type === 'boolean' ||
139	    type === 'object'
140	  );
141	}
142	
143	/**
144	 * Gets a value from a nested object using a key path array iteratively.
145	 */
146	export function getNestedValue(obj: unknown, path: string[]): unknown {
147	  let current = obj;
148	  for (const key of path) {
149	    if (!isRecord(current) || !(key in current)) {
150	      return undefined;
151	    }
152	    current = current[key];
153	  }
154	  return current;
155	}
156	
157	/**
158	 * Get the effective value for a setting falling back to the default value
159	 */
160	export function getEffectiveValue(
161	  key: string,
162	  settings: Settings,
163	): SettingsValue {
164	  const definition = getSettingDefinition(key);
165	  if (!definition) {
166	    return undefined;
167	  }
168	
169	  const path = key.split('.');
170	
171	  // Check the current scope's settings first
172	  const value = getNestedValue(settings, path);
173	  if (value !== undefined && isSettingsValue(value)) {
174	    return value;
175	  }
176	
177	  // Return default value if no value is set anywhere
178	  return definition.default;
179	}
180	
181	export function getAllSettingKeys(): string[] {
182	  return Object.keys(getFlattenedSchema());
183	}
184	
185	export function getSettingsByType(
186	  type: SettingsType,
187	): Array<SettingDefinition & { key: string }> {
188	  return Object.values(getFlattenedSchema()).filter(
189	    (definition) => definition.type === type,
190	  );
191	}
192	
193	export function getSettingsRequiringRestart(): Array<
194	  SettingDefinition & {
195	    key: string;
196	  }
197	> {
198	  return Object.values(getFlattenedSchema()).filter(
199	    (definition) => definition.requiresRestart,
200	  );
201	}
202	
203	/**
204	 * Validate if a setting key exists in the schema
205	 */
206	export function isValidSettingKey(key: string): boolean {
207	  return key in getFlattenedSchema();
208	}
209	
210	export function getSettingCategory(key: string): string | undefined {
211	  return getFlattenedSchema()[key]?.category;
212	}
213	
214	export function shouldShowInDialog(key: string): boolean {
215	  return getFlattenedSchema()[key]?.showInDialog ?? true; // Default to true for backward compatibility
216	}
217	
218	export function getDialogSettingKeys(): string[] {
219	  return Object.values(getFlattenedSchema())
220	    .filter((definition) => definition.showInDialog !== false)
221	    .map((definition) => definition.key);
222	}
223	
224	/**
225	 * Get all settings that should be shown in the dialog, grouped by category like "Advanced", "General", etc.
