}", "newString": "/**
 * Formats a setting value for display, appending its unit if defined.
 *
 * For percentage units, the value is rendered as "raw value (percentage
 * equivalent)" (e.g. "0.5 (50%)"). For any other unit, the unit is appended
 * directly to the value (e.g. "300 seconds").
 */
function formatValueWithUnit(
  value: SettingsValue,
  unit: string | undefined,
): string {
  const valueString = String(value);

  if (!unit) {
    return valueString;
  }

  if (unit === 'percentage') {
    const numericValue = Number(value);
    if (Number.isFinite(numericValue)) {
      const percentage = `${(numericValue * 100).toFixed(0)}%`;
      return `${valueString} (${percentage})`;
    }
    return valueString;
  }

  return `${valueString} ${unit}`;
}

/**
 * Appends a star (*) to settings that exist in the scope
 */
export function getDisplayValue(
  key: string,
  scopeSettings: Settings,
  _mergedSettings: Settings,
): string {
  const definition = getSettingDefinition(key);
  const existsInScope = isInSettingsScope(key, scopeSettings);

  let value: SettingsValue;
  if (existsInScope) {
    value = getEffectiveValue(key, scopeSettings);
  } else {
    value = getDefaultValue(key);
  }

  let valueString: string;

  if (definition?.type === 'enum' && definition.options) {
    const option = definition.options?.find((option) => option.value === value);
    valueString = option?.label ?? `${value}`;
  } else {
    valueString = formatValueWithUnit(value, definition?.unit);
  }

  if (existsInScope) {
    return `${valueString}*`;
